/bin/bash -lc "python - <<'PY'
from pathlib import Path
import json
s=Path('reference/session'); p=json.loads((s/'plan-v2.json').read_text())
print('KEYS',p.keys())
for k,v in p.items():
 if k"'!='"'tasks': print(k, json.dumps(v,ensure_ascii=False))
for t in p['tasks']:
 print(t['id'], t['kind'],t['status'], t['depends_on'])
print('FILES')
for d in [s/'execution', s/'evaluations',Path('reference/step-05-execute-v2/revise-flow')]:
 for f in sorted(d.rglob('*')):
  if f.is_file() and not f.name.startswith('README'): print(f, f.stat().st_size)
print('TARGETS')
for f in [s/'evaluations/flow-v2-check.md',s/'evaluations/plan-v2/flow-v2-review.md',Path('reference/step-05-execute-v2/revise-flow/evaluation/evaluator.md')]: print(f, f.exists())
PY"

